describe("Actions summary cache generation", () => {
  it.each(filteredRunListLegacyKeys)(
    "retires only custom-media shaped list keys: $path $shape $query",
    async (fixture) => {
      const request = validateRelayRequest({
        pool: "maintainers",
        method: "GET",
        path: fixture.path,
        query: fixture.query,
        headers: {
          ...(fixture.shape === "unshaped"
            ? {}
            : { "x-octopool-public-shape": "actions-summary-v1" }),
          ...(fixture.shape === "default" ? {} : { accept: "application/json; charset=utf-8" }),
        },
      });
      const route = classifyRoute(request, defaultPolicy("openclaw"));
      const keys = [
        await githubCacheKey(request.pool, request, route),
        await githubCacheKey(request.pool, request, route, { kind: "pat", id: "primary" }),
      ];
      for (const [index, old] of [fixture.shared, fixture.identity].entries()) {
        if (fixture.shape === "parameterized") expect(keys[index]).not.toBe(old);
        else expect(keys[index]).toBe(old);
      }
    },
  );

  it.each(currentV2ActionsKeys)(
    "retires current-v2 $name shared and identity keys",
    async (fixture) => {
      const request = validateRelayRequest({
        pool: "maintainers",
        method: "GET",
        path: fixture.path,
        query: fixture.query,
        headers: { "x-octopool-public-shape": "actions-summary-v1" },
      });
      const route = classifyRoute(request, defaultPolicy("openclaw"));
      expect(await githubCacheKey(request.pool, request, route)).not.toBe(fixture.shared);
      expect(
        await githubCacheKey(request.pool, request, route, { kind: "pat", id: "primary" }),
      ).not.toBe(fixture.identity);
    },
  );
  it.each([
    ["actions/runs/33167365292", {}],
    ["actions/runs/33167365221/attempts/1", {}],
    ["actions/runs", { limit: "20", branch: "main" }],
    ["actions/runs", { limit: "100" }],
    ["actions/workflows/ci.yml/runs", { limit: "20", status: "failure" }],
  ])("retires legacy %s keys including canonical supersets", async (suffix, query) => {
    const request = validateRelayRequest({
      pool: "maintainers",
      method: "GET",
      path: `/repos/openclaw/Peekaboo/${suffix}`,
      query,
      headers: { "x-octopool-public-shape": "actions-summary-v1" },
    });
    const route = classifyRoute(request, defaultPolicy("openclaw"));
    for (const candidate of [
      request,
      runListSupersetView(request, route)?.cacheRequest ?? request,
    ]) {
      for (const identity of [undefined, { kind: "pat" as const, id: "primary" }]) {
        expect(await githubCacheKey(request.pool, candidate, route, identity)).not.toBe(
          await legacyActionsKey(candidate, route, identity, "publication-v1"),
        );
      }
    }
  });

  it.each([
    ["actions/runs/33167365292", undefined],
    ["actions/runs", undefined],
    ["actions/workflows/ci.yml/runs", undefined],
    ["actions/runs/33167365292/attempts/1/jobs", "actions-jobs-v1"],
    ["pulls/651", "pr-summary-v1"],
  ])("composes protocol epoch with unrelated %s (%s) keys", async (suffix, shape) => {
    const request = validateRelayRequest({
      pool: "maintainers",
      method: "GET",
      path: `/repos/openclaw/Peekaboo/${suffix}`,
      headers: shape === undefined ? {} : { "x-octopool-public-shape": shape },
    });
    const route = classifyRoute(request, defaultPolicy("openclaw"));
    expect(await githubCacheKey(request.pool, request, route)).toBe(
      await legacyActionsKey(request, route, undefined, "publication-v1"),
    );
  });
});

import { hashToken } from "../../src/auth";
import type { RelayRequest, RouteInfo } from "../../src/types";

// Freeze the pre-fix key layout independently of the production key generator.
export function legacyActionsKey(
  request: RelayRequest,
  route: RouteInfo,
  identity?: { kind: string; id: string },
  protocolEpoch?: string,
) {
  return hashToken(
    JSON.stringify({
      ...(protocolEpoch === undefined ? {} : { protocol_epoch: protocolEpoch }),
      pool: request.pool,
      method: request.method,
      path: request.path,
      query: Object.fromEntries(
        Object.entries(request.query ?? {})
          .filter(
            ([key, value]) =>
              !(key === "page" && value === "1") && !(key === "per_page" && value === "30"),
          )
          .sort(([a], [b]) => a.localeCompare(b)),
      ),
      headers:
        request.headers?.["x-octopool-public-shape"] === undefined
          ? {}
          : { "x-octopool-public-shape": request.headers["x-octopool-public-shape"] },
      route_key: route.routeKey,
      ...(identity === undefined ? {} : { identity: `${identity.kind}:${identity.id}` }),
    }),
  );
}

