const ago = (seconds: number) => new Date(now - seconds * 1_000).toISOString();
const collections = [
  ["commits/abc1234/check-runs", "check_runs", 300],
  ["commits/main/check-runs", "check_runs", 120],
  ["commits/abc1234/check-suites", "check_suites", 300],
  ["commits/main/check-suites", "check_suites", 120],
  ["check-suites/42/check-runs", "check_runs", 300],
  ["commits/abc1234/status", "statuses", 300],
  ["commits/main/status", "statuses", 120],
  ["commits/abc1234/statuses", "array", 300],
  ["commits/main/statuses", "array", 120],
  ["statuses/abc1234", "array", 300],
] as const;

afterEach(() => vi.restoreAllMocks());

describe.each(collections)("settled CI TTL: %s", (tail, shape, cap) => {
  const route = classifyRoute(
    { pool: "maintainers", method: "GET", path: `/repos/openclaw/octopool/${tail}` },
    defaultPolicy("openclaw"),
  );
  const checks = shape === "check_runs" || shape === "check_suites";
  const item = (timestamp: unknown) =>
    checks
      ? { status: "completed", completed_at: timestamp }
      : { state: "success", updated_at: timestamp };
  const ttl = (items: unknown[], state = "success") =>
    cacheTTLSeconds(route, {
      status: 200,
      headers: {},
      body: shape === "array" ? items : { state, [shape]: items },
    });

  it.each([
    [0, 60],
    [600, 60],
    [900, 90],
    [1_809, 180],
    [3_000, 300],
    [86_400, 300],
    [-100, 60],
  ])("uses the newest item at age %i and bounds fresh/stale lifetimes", (age, expected) => {
    vi.spyOn(Date, "now").mockReturnValue(now);
    expect(ttl([item(ago(86_400)), item(ago(age))])).toBe(Math.min(expected, cap));
    expect(ttl([item(ago(age)), item(ago(86_400))])).toBe(Math.min(expected, cap));
    expect(staleCacheSeconds(route, cap)).toBe(300);
  });

  it.each([undefined, null, "invalid", 123])(
    "keeps a missing/invalid item timestamp %j at 60s",
    (timestamp) => {
      vi.spyOn(Date, "now").mockReturnValue(now);
      expect(ttl([item(ago(86_400)), item(timestamp)])).toBe(60);
    },
  );

  it("keeps empty, malformed, active and pending collections at 60s", () => {
    vi.spyOn(Date, "now").mockReturnValue(now);
    expect(ttl([])).toBe(60);
    expect(ttl([null])).toBe(60);
    expect(
      ttl([item(ago(86_400)), { ...item(ago(86_400)), status: "in_progress", state: "pending" }]),
    ).toBe(60);
    if (shape === "statuses") expect(ttl([item(ago(86_400))], "pending")).toBe(60);
    expect(cacheTTLSeconds(route)).toBe(60);
  });

  it("uses a later update even when completion is old", () => {
    vi.spyOn(Date, "now").mockReturnValue(now);
    expect(ttl([{ ...item(ago(86_400)), completed_at: ago(86_400), updated_at: ago(900) }])).toBe(
      90,
    );
    expect(ttl([{ ...item(ago(86_400)), completed_at: ago(86_400), updated_at: "invalid" }])).toBe(
      60,
    );
  });
});

import { env } from "cloudflare:workers";
import { describe, expect, it, vi } from "vitest";
import { hashToken } from "../../src/auth";
import {
  GITHUB_EDGE_CACHE_NAMESPACE,
  githubCacheKey,
  type CachedGitHubResponse,
} from "../../src/cache";
import { CACHE_PUBLICATION_EPOCH } from "../../src/cache-publication";
import { loadIdentities } from "../../src/db";
import { deleteEdgeJSON, readEdgeJSON, writeEdgeJSON } from "../../src/edge-cache";
import { classifyRoute, defaultPolicy } from "../../src/policy";
import { seedPublicRepoProof, writeOwnedGitHubCache } from "./cache-publication-fixture";
import { bearer, jsonResponse, POOL, relay, seedPool } from "./harness";

const sha = "a".repeat(40);
const path = `/repos/openclaw/octopool/commits/${sha}/check-runs`;
const result = (status: string) => ({
  total_count: 1,
  check_runs: [
    { id: 1, head_sha: sha, status, conclusion: status === "completed" ? "success" : null },
  ],
});

describe("mutable commit CI cache", () => {
  it("refreshes completed checks after a same-SHA rerun within the mutable TTL", async () => {
    await seedPool();
    let status = "completed";
    const upstream = vi.fn<typeof fetch>(async (input, init) => {
      const request = new Request(input, init);
      expect(request.url).toBe(`https://api.github.com${path}`);
      expect(bearer(request)).toBeUndefined();
      return jsonResponse(result(status));
    });
    vi.stubGlobal("fetch", upstream);
    const request = { pool: POOL, method: "GET" as const, path };
    const key = await githubCacheKey(
      POOL,
      request,
      classifyRoute(request, defaultPolicy("openclaw")),
    );

    expect(await (await relay(path)).json()).toMatchObject({
      body: result("completed"),
      relay: { cache: "miss" },
    });
    status = "in_progress";
    expect(await (await relay(path)).json()).toMatchObject({
      body: result("completed"),
      relay: { cache: "hit" },
    });
    expect(upstream).toHaveBeenCalledTimes(1);

    // Age the actual first publication in both stores instead of changing the
    // Worker clock while SQLite's independent storage clock remains unchanged.
    await env.DB.prepare(`UPDATE github_cache_entries SET
      created_at = datetime(created_at, '-61 seconds'),
      expires_at = datetime(expires_at, '-61 seconds'),
      stale_expires_at = datetime(stale_expires_at, '-61 seconds') WHERE cache_key = ?`)
      .bind(key)
      .run();
    const edge = await readEdgeJSON<CachedGitHubResponse & { protocol_epoch: string }>(
      GITHUB_EDGE_CACHE_NAMESPACE,
      key,
    );
    expect(edge).toBeDefined();
    const age = (value: string) =>
      new Date(Date.parse(`${value}Z`) - 61_000).toISOString().slice(0, 19).replace("T", " ");
    await writeEdgeJSON(
      GITHUB_EDGE_CACHE_NAMESPACE,
      key,
      {
        ...edge,
        created_at: age(edge!.created_at),
        expires_at: age(edge!.expires_at),
      },
      3_600,
    );

    expect(await (await relay(path)).json()).toMatchObject({
      body: result("completed"),
      relay: { cache: "stale", stale_reason: "stale_while_revalidate" },
    });
    expect(await (await relay(path)).json()).toMatchObject({
      body: result("in_progress"),
      relay: { cache: "hit" },
    });
    expect(upstream).toHaveBeenCalledTimes(2);
    expect(
      await env.DB.prepare(`SELECT unixepoch(expires_at) - unixepoch(created_at) AS fresh,
      unixepoch(stale_expires_at) - unixepoch(expires_at) AS stale
      FROM github_cache_entries WHERE cache_key = ?`)
        .bind(key)
        .first(),
    ).toEqual({ fresh: 60, stale: 300 });
  });

  it.each(["edge", "shared", "identity", "stale"])(
    "retires old terminal %s entries and validators",
    async (storage) => {
      await seedPool();
      const request = { pool: POOL, method: "GET" as const, path };
      const route = classifyRoute(request, defaultPolicy("openclaw"));
      const identity =
        storage === "identity" ? (await loadIdentities(env, POOL, route))[0] : undefined;
      const key = await hashToken(
        JSON.stringify({
          protocol_epoch: CACHE_PUBLICATION_EPOCH,
          pool: POOL,
          method: "GET",
          path,
          query: {},
          headers: {},
          route_key: route.routeKey,
          ...(identity === undefined ? {} : { identity: `${identity.kind}:${identity.id}` }),
        }),
      );
      expect(await githubCacheKey(POOL, request, route, identity)).not.toBe(key);
      await seedPublicRepoProof(env, route);
      expect(
        await writeOwnedGitHubCache(
          env,
          key,
          request,
          route,
          {
            status: 200,
            body: result("completed"),
            headers: { etag: '"old-terminal"', "x-ratelimit-resource": "core" },
          },
          identity,
        ),
      ).toBe("shared");
      await env.DB.prepare(`UPDATE github_cache_entries SET expires_at = datetime('now', '+1 hour'),
      stale_expires_at = datetime('now', '+25 hours') WHERE cache_key = ?`)
        .bind(key)
        .run();
      const edge = await readEdgeJSON<CachedGitHubResponse & { protocol_epoch: string }>(
        GITHUB_EDGE_CACHE_NAMESPACE,
        key,
      );
      expect(edge).toBeDefined();
      if (storage === "edge") {
        await writeEdgeJSON(
          GITHUB_EDGE_CACHE_NAMESPACE,
          key,
          {
            ...edge,
            expires_at: new Date(Date.now() + 3_600_000)
              .toISOString()
              .slice(0, 19)
              .replace("T", " "),
          },
          3_600,
        );
      } else {
        await deleteEdgeJSON(GITHUB_EDGE_CACHE_NAMESPACE, key);
      }
      if (storage === "stale") {
        await env.DB.prepare(`UPDATE github_cache_entries SET created_at = datetime('now', '-1 hour'),
        expires_at = datetime('now', '-1 second') WHERE cache_key = ?`)
          .bind(key)
          .run();
        await env.DB.prepare("UPDATE identities SET status = 'disabled'").run();
      }
      const upstream = vi.fn<typeof fetch>(async (input, init) => {
        const request = new Request(input, init);
        expect(request.url).toBe(`https://api.github.com${path}`);
        expect(request.headers.get("if-none-match")).toBeNull();
        if (storage === "stale" || (storage === "identity" && bearer(request) === undefined)) {
          return jsonResponse({ message: "unavailable" }, 503);
        }
        return jsonResponse(result("queued"));
      });
      // A failed anonymous resource fetch requires a live visibility probe;
      // the seeded proof only covers serving the old cached body.
      const publicRepoProbe = vi.fn(() => jsonResponse({ private: false }));
      const fetchWithPublicRepoProbe: typeof fetch = async (input, init) => {
        if (new Request(input, init).url === "https://api.github.com/repos/openclaw/octopool") {
          return publicRepoProbe();
        }
        return upstream(input, init);
      };
      vi.stubGlobal("fetch", fetchWithPublicRepoProbe);
      const response = await relay(path);
      if (storage === "stale") {
        expect(response.status).toBe(424);
      } else {
        expect(await response.json()).toMatchObject({
          body: result("queued"),
          relay: { cache: "miss" },
        });
      }
      expect(upstream).toHaveBeenCalledTimes(storage === "identity" ? 2 : 1);
      expect(publicRepoProbe).toHaveBeenCalledTimes(
        storage === "identity" || storage === "stale" ? 1 : 0,
      );
    },
  );
});

import { vi } from "vitest";
import type {
  CacheFillAcquisition,
  CacheFillCoordinator,
  CacheFillOutcome,
} from "../src/cache-fill";
import { CACHE_PUBLICATION_EPOCH, type PublicationOwner } from "../src/cache-publication";

export function fixtureOwner(token = "fixture", resource = "cache:cache-key"): PublicationOwner {
  return {
    id: 1,
    protocol_epoch: CACHE_PUBLICATION_EPOCH,
    resource_key: resource,
    owner_token: token,
    lease_until_ms: Date.now() + 8_000,
  };
}

export function fakeCacheFillCoordinator(
  acquisitions: (
    | { kind: "owner"; token: string }
    | { kind: "completed"; outcome: CacheFillOutcome }
    | { kind: "retry" }
  )[],
) {
  let index = 0;
  return {
    acquirePublication: vi.fn(async (resource: string): Promise<CacheFillAcquisition> => {
      const acquisition = acquisitions[index++];
      if (acquisition === undefined) throw new Error("unexpected publication acquisition");
      if (acquisition.kind === "owner")
        return { kind: "owner", owner: fixtureOwner(acquisition.token, resource) };
      return acquisition;
    }),
    tryAcquirePublication: vi.fn(async () => undefined),
    renewPublication: vi.fn(async () => true),
    completePublication: vi.fn(async () => true),
  } satisfies CacheFillCoordinator;
}

import { readFileSync } from "node:fs";
import { URL } from "node:url";
import { afterEach, describe, expect, it, vi } from "vitest";
import { withGitHubEgress } from "../src/github-egress";
import { parseActionsRunHTML, parseActionsRunListHTML } from "../src/github-html-actions";
import { callGitHubWeb } from "../src/github-web";
import { classifyRoute, defaultPolicy, validateRelayRequest } from "../src/policy";

const fixture = (name: string) =>
  readFileSync(
    new URL(`./fixtures/actions-list-hydration/${name}.html.txt`, import.meta.url),
    "utf8",
  );
const manualID = 35575007986;
const manual = fixture("manual-queued");
const parsedManualSHA = /\/commit\/([a-f0-9]{40})/.exec(manual)![1]!;
const runPage = (id: number) => manual.replaceAll(String(manualID), String(id));
const listPath = "/openclaw/openclaw/actions";
function githubPagePath(input: string): string {
  const url = new URL(input);
  expect(url.origin).toBe("https://github.com");
  return url.pathname;
}
const listPage = (count: number, complete = 0) =>
  `<strong>${count} workflow runs</strong>` +
  Array.from({ length: count }, (_, index) => {
    const id = index + 1;
    return `<div class="Box-row js-socket-channel js-updatable-content">
      <a href="/openclaw/openclaw/actions/runs/${id}" aria-label="queued: CI">
        <span class="markdown-title">CI</span>
      </a>
      <span class="text-bold">CI</span> #${id}: workflow dispatch
      <relative-time datetime="2026-09-21T07:52:36Z"></relative-time>
      ${index < complete ? `<a href="/openclaw/openclaw/commit/${parsedManualSHA}">commit</a>` : ""}
    </div>`;
  }).join("");

async function readList(
  options: {
    workflow?: boolean;
    limit?: number;
    timeout?: number;
    api?: boolean;
    rules?: { pattern: string; replacement: string }[];
  } = {},
) {
  const request = validateRelayRequest({
    pool: "maintainers",
    method: "GET",
    path: `/repos/openclaw/openclaw/actions/${options.workflow ? "workflows/ci.yml/runs" : "runs"}`,
    query: { per_page: String(options.limit ?? 25) },
    headers: { "x-octopool-public-shape": "actions-summary-v1" },
  });
  return callGitHubWeb(
    withGitHubEgress(
      { REQUEST_TIMEOUT_MS: String(options.timeout ?? 30000) } as Env,
      options.rules ?? [],
    ),
    request,
    classifyRoute(request, defaultPolicy("openclaw")),
    { skipAnonymousAPI: !options.api },
  );
}

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
  vi.useRealTimers();
});

function fakeTimeouts() {
  vi.useFakeTimers();
  vi.spyOn(AbortSignal, "timeout").mockImplementation((ms) => {
    const controller = new AbortController();
    setTimeout(() => controller.abort(new DOMException("Timed out", "TimeoutError")), ms);
    return controller.signal;
  });
}

describe("Actions list hydration", () => {
  it.each([
    ["manual-queued", manualID, "queued"],
    ["manual-active", 35575038033, "in_progress"],
    ["push-pending", 35575012764, "pending"],
  ] as const)("parses owned metadata in the live %s page", (name, id, status) => {
    expect(parseActionsRunHTML(fixture(name), "openclaw", "openclaw", id)).toMatchObject({
      id,
      status,
      conclusion: null,
      event: name === "push-pending" ? "push" : "workflow_dispatch",
      head_sha: expect.stringMatching(/^[a-f0-9]{40}$/),
    });
  });

  it.each(["pr-queued", "pr-target"])("still rejects %s without an owned commit SHA", (name) => {
    const id = name === "pr-queued" ? 35574986404 : 35575041909;
    const html = fixture(name);
    expect(html).not.toMatch(/\/commit\/[a-f0-9]{40}/);
    expect(parseActionsRunHTML(html, "openclaw", "openclaw", id)).toBeUndefined();
    expect(
      parseActionsRunHTML(
        `${html}<a href="/openclaw/openclaw/commit/${parsedManualSHA}">unowned</a>`,
        "openclaw",
        "openclaw",
        id,
      ),
    ).toBeUndefined();
  });

  it.each([
    [
      "absent graph",
      (html: string) =>
        html.slice(0, html.indexOf('<div role="region" aria-label="Workflow run graph"')),
    ],
    ["foreign graph", (html: string) => html.replace("/graph_partial", "/foreign_graph_partial")],
    ["wrong event", (html: string) => html.replace("on: workflow_dispatch", "on: push")],
    [
      "missing time",
      (html: string) => html.replace(/<relative-time\b[\s\S]*?<\/relative-time>/, ""),
    ],
    [
      "duplicate time",
      (html: string) =>
        html.replace(/<relative-time\b[\s\S]*?<\/relative-time>/, "$& Manually triggered $&"),
    ],
  ] as const)("rejects manual trigger with %s", (_name, transform) => {
    expect(
      parseActionsRunHTML(transform(manual), "openclaw", "openclaw", manualID),
    ).toBeUndefined();
  });

  it.each([
    ["list", false, 25],
    ["workflow", true, 22],
  ] as const)(
    "rejects captured %s before any hydration, even for limit 1",
    async (name, workflow, count) => {
      const html = fixture(name);
      const parsed = parseActionsRunListHTML(html, "openclaw", "openclaw")!;
      expect(parsed.workflow_runs).toHaveLength(25);
      expect(parsed.workflow_runs.filter((run) => !run.head_sha || !run.event)).toHaveLength(count);
      const upstream = vi.fn(async () => new Response(html));
      vi.stubGlobal("fetch", upstream);
      expect(await readList({ workflow, limit: 1 })).toBeUndefined();
      expect(upstream).toHaveBeenCalledOnce();
    },
  );

  it.each([8, 9])("bounds hydration at eight cards: %i", async (count) => {
    const upstream = vi.fn(async (url: string) => {
      const path = githubPagePath(url);
      return new Response(
        path === listPath ? listPage(count) : runPage(Number(path.split("/").at(-1))),
      );
    });
    vi.stubGlobal("fetch", upstream);
    const result = await readList();
    if (count === 8) {
      expect(result?.body).toMatchObject({
        total_count: 8,
        workflow_runs: Array.from({ length: 8 }, (_, i) => ({
          id: i + 1,
          event: "workflow_dispatch",
          head_sha: parsedManualSHA,
        })),
      });
      expect(upstream).toHaveBeenCalledTimes(9);
    } else {
      expect(result).toBeUndefined();
      expect(upstream).toHaveBeenCalledOnce();
    }
  });

  it("counts only incomplete cards, preserving a full 25-run result", async () => {
    const upstream = vi.fn(async (url: string) => {
      const path = githubPagePath(url);
      return new Response(
        path === listPath ? listPage(25, 17) : runPage(Number(path.split("/").at(-1))),
      );
    });
    vi.stubGlobal("fetch", upstream);
    const result = await readList();
    expect(result?.body).toHaveProperty("workflow_runs.length", 25);
    expect(upstream).toHaveBeenCalledTimes(9);
  });

  it("aborts siblings on the first failed hydration and falls back without a partial list", async () => {
    const aborted = vi.fn();
    const upstream = vi.fn(async (url: string, init: RequestInit) => {
      const parsed = new URL(url);
      if (
        parsed.origin === "https://api.github.com" &&
        parsed.pathname === "/repos/openclaw/openclaw/actions/runs"
      )
        return Response.json({ exact: true });
      const path = githubPagePath(url);
      if (path === listPath) return new Response(listPage(3));
      if (path === `${listPath}/runs/1`) return new Response(runPage(1));
      if (path === `${listPath}/runs/2`) return new Response("missing metadata");
      return new Promise<Response>((_resolve, reject) =>
        init.signal!.addEventListener(
          "abort",
          () => {
            aborted();
            reject(init.signal!.reason);
          },
          { once: true },
        ),
      );
    });
    vi.stubGlobal("fetch", upstream);
    expect(await readList({ api: true })).toMatchObject({
      backend: "github",
      body: { exact: true },
    });
    expect(aborted).toHaveBeenCalledOnce();
    expect(upstream).toHaveBeenCalledTimes(5);
  });

  it("propagates string protection failures while aborting hydration", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => new Response(listPage(1))),
    );
    await expect(
      readList({ rules: [{ pattern: "/actions/runs/1", replacement: "blocked" }] }),
    ).rejects.toMatchObject({ code: "string_rewrite_denied" });
  });

  it("rejects conflicting exact events instead of overwriting the list evidence", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(async (url: string) => {
        const path = githubPagePath(url);
        return new Response(
          path === listPath ? listPage(1).replace("workflow dispatch", "pull request") : runPage(1),
        );
      }),
    );
    expect(await readList()).toBeUndefined();
  });

  it.each(["run headers", "run body", "patch body", "redirect"])(
    "bounds stalled %s by the shared 2500 ms hydration deadline",
    async (stage) => {
      fakeTimeouts();
      const cancelled = vi.fn();
      const pendingBody = () => new Response(new ReadableStream({ cancel: cancelled }));
      const upstream = vi.fn(async (url: string, init: RequestInit) => {
        const path = githubPagePath(url);
        const pendingFetch = () =>
          new Promise<Response>((_resolve, reject) =>
            init.signal!.addEventListener(
              "abort",
              () => {
                cancelled();
                reject(init.signal!.reason);
              },
              { once: true },
            ),
          );
        if (path === listPath) {
          return new Response(listPage(1));
        }
        if (path.endsWith(".patch")) return pendingBody();
        if (path === "/redirected") return pendingFetch();
        if (stage === "redirect")
          return new Response(null, { status: 302, headers: { location: "/redirected" } });
        if (stage === "run headers") return pendingFetch();
        if (stage === "run body") return pendingBody();
        return new Response(runPage(1).replaceAll(parsedManualSHA, parsedManualSHA.slice(0, 7)));
      });
      vi.stubGlobal("fetch", upstream);
      let settled = false;
      const result = readList().then((value) => {
        settled = true;
        return value;
      });
      await vi.advanceTimersByTimeAsync(2499);
      expect(settled).toBe(false);
      await vi.advanceTimersByTimeAsync(1);
      expect(await result).toBeUndefined();
      expect(cancelled).toHaveBeenCalledOnce();
      expect(AbortSignal.timeout).toHaveBeenCalledWith(2500);
      if (stage.startsWith("run") || stage === "redirect")
        expect(AbortSignal.timeout).toHaveBeenCalledWith(5000);
    },
  );

  it.each(["headers", "body"])(
    "gives hydration its full deadline after slow list %s",
    async (stage) => {
      fakeTimeouts();
      const delay = () => new Promise<void>((resolve) => setTimeout(resolve, 2000));
      const upstream = vi.fn(async (url: string, init: RequestInit) => {
        const path = githubPagePath(url);
        if (path === listPath) {
          if (stage === "headers") {
            await delay();
            init.signal!.throwIfAborted();
            return new Response(listPage(1));
          }
          return new Response(
            new ReadableStream({
              async start(controller) {
                await delay();
                if (init.signal!.aborted) controller.error(init.signal!.reason);
                else {
                  controller.enqueue(new TextEncoder().encode(listPage(1)));
                  controller.close();
                }
              },
            }),
          );
        }
        await delay();
        init.signal!.throwIfAborted();
        return new Response(runPage(1));
      });
      vi.stubGlobal("fetch", upstream);
      const result = readList();
      await vi.advanceTimersByTimeAsync(2000);
      expect(upstream).toHaveBeenCalledTimes(2);
      await vi.advanceTimersByTimeAsync(2000);
      expect(await result).toMatchObject({ backend: "web", body: { workflow_runs: [{ id: 1 }] } });
      expect(AbortSignal.timeout).toHaveBeenCalledWith(30000);
    },
  );

  it("shares the hydration deadline across run pages and commit patches", async () => {
    fakeTimeouts();
    const cancelled = vi.fn();
    const upstream = vi.fn(async (url: string, init: RequestInit) => {
      const path = githubPagePath(url);
      if (path === listPath) return new Response(listPage(1));
      if (path.endsWith(".patch")) return new Response(new ReadableStream({ cancel: cancelled }));
      await new Promise((resolve) => setTimeout(resolve, 2000));
      init.signal!.throwIfAborted();
      return new Response(runPage(1).replaceAll(parsedManualSHA, parsedManualSHA.slice(0, 7)));
    });
    vi.stubGlobal("fetch", upstream);
    let settled = false;
    const result = readList().then((value) => {
      settled = true;
      return value;
    });
    await vi.advanceTimersByTimeAsync(2499);
    expect(upstream).toHaveBeenCalledTimes(3);
    expect(settled).toBe(false);
    await vi.advanceTimersByTimeAsync(1);
    expect(await result).toBeUndefined();
    expect(cancelled).toHaveBeenCalledOnce();
  });

  it("honors a shorter configured timeout", async () => {
    const upstream = vi.fn(
      (_url: string, init: RequestInit) =>
        new Promise<Response>((_resolve, reject) =>
          init.signal!.addEventListener("abort", () => reject(init.signal!.reason), { once: true }),
        ),
    );
    vi.stubGlobal("fetch", upstream);
    const timeout = vi.spyOn(AbortSignal, "timeout");
    expect(await readList({ timeout: 20 })).toBeUndefined();
    expect(timeout).toHaveBeenCalledWith(20);
  });

  it("honors a shorter configured per-page timeout during hydration", async () => {
    fakeTimeouts();
    vi.stubGlobal(
      "fetch",
      vi.fn(async (url: string, init: RequestInit) => {
        if (githubPagePath(url) === listPath) return new Response(listPage(1));
        return new Promise<Response>((_resolve, reject) =>
          init.signal!.addEventListener("abort", () => reject(init.signal!.reason), { once: true }),
        );
      }),
    );
    const result = readList({ timeout: 100 });
    await vi.advanceTimersByTimeAsync(100);
    expect(await result).toBeUndefined();
    expect(AbortSignal.timeout).toHaveBeenCalledWith(100);
    expect(AbortSignal.timeout).toHaveBeenCalledWith(2500);
  });
});

