    ],
    [
      "unowned table outside annotations",
      (html: string) => html.replace(annotation, "<table><tr><td>Unowned</td></tr></table>"),
    ],
    [
      "conflicting job marker",
      (html: string) => html.replace(`check_run_${failedID}`, "check_run_123"),
